69	/**
70	 * Create a goal from an external request (e.g., player asking NPC to investigate).
71	 * Uses the same pipeline as volition: find affordance → checkRequirements → buildSteps.
72	 * Returns null if requirements not met or affordance not found.
73	 */
74	export function createGoalFromRequest(
75	  npcId: string,
76	  affordanceId: string,
77	  ctx: AffordanceContext,
78	  requestedTarget?: string,
79	): NpcGoal | null {
80	  const agent = ctx.agents.get(npcId);
81	  if (!agent || !agent.state.alive || isStatusAbsent(agent.state.status)) return null;
82	
83	  const aff = AFFORDANCE_REGISTRY.find((a) => a.id === affordanceId);
84	  if (!aff) return null;
85	
86	  // Validate requirements (same checkRequirements as volition)
87	  const target = checkRequirements(aff, npcId, agent, ctx);
88	  if (!target) return null;
89	
90	  // If caller specified a target, override location (e.g., "investigate the market")
91	  if (requestedTarget) {
92	    // Try to resolve as location name
93	    for (const loc of ctx.locations.values()) {
94	      if (loc.name.toLowerCase().includes(requestedTarget.toLowerCase())) {
95	        target.targetLocation = loc.name;
96	        break;
97	      }
98	    }
99	  }
100	
101	  // Build proper steps using the same templates as volition
102	  const steps = buildSteps(aff, npcId, agent, target, ctx);
103	  const home = ctx.npcHomes.get(npcId) ?? agent.state.location;
104	
105	  return {
106	    id: crypto.randomUUID(),
107	    type: aff.goalType,
108	    ownerId: npcId,
109	    priority: Math.max(aff.goalPriority, 7), // Player request = at least priority 7
110	    state: 'pending',
111	    steps,
112	    currentStep: 0,
113	    data: {
114	      affordanceId: aff.id,
115	      targetId: target.targetId,
116	      targetName: target.targetName,
117	      requestedBy: Array.from(ctx.agents.values()).find(a => a.profile.isPlayer)?.profile.id,
118	      ...target.extra,
119	    },
120	    createdAtMinute: ctx.gameMinute,
121	    homeLocation: home,
122	  };
123	}
