199	// ─── Reactive Entry Point (on CE event) ───
200	
201	/**
202	 * Evaluate reactive affordances for NPCs affected by an event.
203	 * Called from handleEventForGoals when CE fires an event.
204	 * Returns goals to add to GoalManager.
205	 */
206	export function evaluateReactiveVolition(
207	  event: WorldEvent,
208	  ctx: AffordanceContext,
209	  existingGoalTypes: (npcId: string) => string[],
210	): NpcGoal[] {
211	  const goals: NpcGoal[] = [];
212	  const affectedTargets = (event.payload?.affectedTargets as string[]) ?? [];
213	  // Reactors = affected targets + event object (target of the event can react: wanted→flee, arrested→resist)
214	  // Subject excluded by default (killer shouldn't get report_crime), added only for body discovery
215	  const reactors = new Set(affectedTargets);
216	  if (event.object) reactors.add(event.object);
217	  const bodyDiscoveryType = getBodyDiscoveryEventType();
218	  if (event.subject && bodyDiscoveryType && event.type === bodyDiscoveryType) {
219	    reactors.add(event.subject);
220	  }
221	  // Subject reacts for event types flagged subjectReacts (e.g., WANTED_STATUS → criminal flees)
222	  if (event.subject && subjectReacts(event.type)) {
223	    reactors.add(event.subject);
224	  }
225	
226	  for (const npcId of reactors) {
227	    const agent = ctx.agents.get(npcId);
228	    if (!agent || !agent.state.alive || isStatusAbsent(agent.state.status)) continue;
229	    if (agent.profile.isPlayer) continue; // Player makes own decisions
230	
231	    // Find reactive affordances matching this event
232	    for (const aff of AFFORDANCE_REGISTRY) {
233	      if (!aff.eventBoost) continue;
234	      if (!aff.eventBoost.eventTypes.includes(event.type)) continue;
235	
236	      // Relation to victim filter
237	      if (aff.eventBoost.requiresRelationToVictim) {
238	        const victimId = event.object;
239	        if (!victimId) continue;
240	        const rel = agent.state.relationships?.getRelationship(victimId);
241	        if (!rel || rel.sentiment < 0.2) continue; // only close relationships trigger grief
242	      }
243	
244	      // Don't create same goal type if already active
245	      const existing = existingGoalTypes(npcId);
246	      if (existing.includes(aff.goalType)) continue;
247	
248	      // Respect affordance cooldowns — same system as proactive, prevents reactive spam
249	      if (ctx.cooldowns) {
250	        const npcCooldowns = ctx.cooldowns.get(npcId);
251	        if (npcCooldowns) {
252	          const expires = npcCooldowns.get(aff.id);
253	          if (expires !== undefined && ctx.gameMinute < expires) continue;
254	        }
255	      }
256	
257	      // Only react to events from CE cascade (sourceRule), goal execution (sourceEvent), or body discovery
258	      const isBodyDiscovery = bodyDiscoveryType && event.type === bodyDiscoveryType;
259	      if (!isBodyDiscovery && !event.payload?.sourceRule && !event.payload?.sourceEvent) continue;
260	
261	      // Check requirements (relaxed for reactive)
262	      const target = checkRequirementsReactive(aff, npcId, agent, ctx, event);
263	      if (!target) continue;
264	
265	      // Compute score with event boost
266	      const baseScore = computeUtility(aff, agent, target);
267	      const boostedScore = Math.min(1, baseScore + aff.eventBoost.boost);
268	
269	      if (boostedScore < MIN_SCORE) continue;
270	
271	      // Reactive uses auto-decision (event urgency makes it obvious)
272	      console.log(`  [AL:reactive] ${agent.profile.name} → ${aff.id} (base ${baseScore.toFixed(2)} + boost ${aff.eventBoost.boost} = ${boostedScore.toFixed(2)}) [${event.type}]`);
273	
274	      const goal = buildGoalFromAffordance(
275	        { definition: aff, score: boostedScore, target },
276	        npcId, agent, ctx,
277	      );
278	      goal.createdAtMinute = ctx.gameMinute;
279	      // Set current motive on agent so all LLM calls carry emotional context
280	      agent.state.currentMotive = goal.data?.reason as string | undefined;
281	      goals.push(goal);
282	      // Apply cooldown so reactive doesn't fire again for this affordance
283	      setAffordanceCooldown(ctx, npcId, aff.id, ctx.gameMinute, aff);
284	      break; // One reactive goal per NPC per event
285	    }
286	  }
287	
288	  return goals;
289	}
