291	// ─── LLM-Driven Decision ───
292	
293	async function llmDecideAndBuild(
294	  scored: ScoredAffordance[],
295	  npcId: string,
296	  agent: Agent,
297	  ctx: AffordanceContext,
298	  onLlmCall?: (label: string, detail: string) => void,
299	  onDecision?: (data: { npcId: string; npcName: string; action: string; target?: string; reason: string; topScore: number; instinctTier: string; alternatives: { verb: string; score: number }[] }) => void,
300	): Promise<NpcGoal | null> {
301	  scored.sort((a, b) => b.score - a.score);
302	
303	  const { system, user } = buildDecisionPrompt(agent, scored, npcId, ctx);
304	
305	  onLlmCall?.('Volition decision', `${agent.profile.name}: ${scored.map((s) => s.definition.id).join(', ')}`);
306	  console.log(`  [AL:llm] ${agent.profile.name} — deciding (${scored.map((s) => `${s.definition.id}:${s.score.toFixed(2)}`).join(', ')})`);
307	
308	  const response = await callLlm(agent, system, user, ctx.volitionTemperature);
309	  if (!response) return null;
310	
311	  console.log(`  [AL:llm] ${agent.profile.name} response: ${response.replace(/\n/g, ' ')}`);
312	
313	  // Parse structured JSON response
314	  let decision: { action: string; target: string; reason: string };
315	  try {
316	    decision = JSON.parse(response);
317	  } catch {
318	    console.log(`  [AL:llm] ${agent.profile.name} — invalid JSON, waiting`);
319	    return null;
320	  }
321	
322	  if (!decision.action) {
323	    console.log(`  [AL:llm] ${agent.profile.name} — no action, waiting`);
324	    return null;
325	  }
326	
327	  const action = decision.action.toLowerCase().trim();
328	  const targetRaw = decision.target?.trim() || '';
329	  const reason = decision.reason || 'no reason given';
330	
331	  // Resolve target — try NPC name first, then location
332	  const locationNames = Array.from(ctx.locations.values()).map((l) => l.name);
333	  const npcNames = Array.from(ctx.agents.entries())
334	    .filter(([id, a]) => {
335	      if (id === npcId || !a.state.alive || a.profile.isPlayer) return false;
336	      return !isStatusAbsent(a.state.status);
337	    })
338	    .map(([, a]) => a.profile.name);
339	
340	  const resolvedNpc = targetRaw ? matchName(targetRaw, npcNames) : undefined;
341	  const resolvedLocation = targetRaw ? matchName(targetRaw, locationNames) : undefined;
342	
343	  // Unified resolution: action + resolved target → ParsedIntention
344	  const parsed = resolveDecision(action, resolvedNpc ?? undefined, resolvedLocation ?? undefined, targetRaw ?? '', reason);
345	
346	  if (!parsed) {
347	    console.log(`  [AL:llm] ${agent.profile.name} — unresolved: ${action} ${targetRaw}, waiting`);
348	    return null;
349	  }
350	
351	  console.log(`  [AL:llm] ${agent.profile.name} → ${parsed.action}${parsed.target ? ' ' + parsed.target : ''} | ${parsed.why}`);
352	
353	  // Emit decision for overlay UI
354	  onDecision?.({
355	    npcId,
356	    npcName: agent.profile.name,
357	    action: parsed.action,
358	    target: parsed.target || undefined,
359	    reason: parsed.why,
360	    topScore: scored[0].score,
361	    instinctTier: getTierName(scored[0].score),
362	    alternatives: scored.slice(0, 5).map(s => ({ verb: s.definition.id, score: Math.round(s.score * 100) / 100 })),
363	  });
364	
365	  // Set current motive on agent regardless of action (even wait carries emotional context)
366	  agent.state.currentMotive = parsed.why || undefined;
367	
368	  // Record talk target for anti-repeat
369	  if (parsed.action === 'talk' && parsed.target) {
370	    recordTalkTarget(npcId, parsed.target, ctx.gameMinute);
371	  }
372	
373	  return intentionToGoal(parsed, npcId, agent, scored, ctx);
374	}
