376	// ─── Decision Prompt Builder ───
377	
378	function buildDecisionPrompt(
379	  agent: Agent,
380	  scored: ScoredAffordance[],
381	  npcId: string,
382	  ctx: AffordanceContext,
383	): { system: string; user: string } {
384	  const bf = agent.profile.bigFive;
385	  const enn = agent.profile.enneagram;
386	
387	  // ── Personality traits as prose ──
388	  const personalityLine = `You are ${bigFiveToDescription(bf)}.`;
389	
390	  // ── Mood prose ──
391	  const mood = agent.state.mood;
392	  let moodLine: string;
393	  if (mood > 0.5) moodLine = 'You feel good — relaxed, at ease.';
394	  else if (mood > 0) moodLine = 'You feel calm and steady.';
395	  else if (mood > -0.3) moodLine = 'You feel slightly on edge, less patient.';
396	  else if (mood > -0.5) moodLine = 'You are tense — jaw tight, irritable.';
397	  else moodLine = 'You are deeply shaken — everything feels heavy and bleak.';
398	
399	  // ── Stress/growth ──
400	  const stressGrowth = getStressGrowthDirective(mood, enn);
401	
402	  // ── Beliefs & relationships (compact) ──
403	  const beliefSummary = agent.state.beliefs?.summarizeForPrompt(3, agent.nameResolver) ?? '';
404	  const relSummary = agent.state.relationships?.summarizeForPrompt() ?? '';
405	
406	  // ── System prompt (identity + personality — no beliefs, those go in user prompt) ──
407	  const systemParts = [
408	    `You are ${agent.profile.name}, a ${agent.profile.role}. Only reference people, places, and events that actually exist. Do not invent details.`,
409	    personalityLine,
410	    `Your deepest fear: ${enn.coreFear}`,
411	    `Your deepest desire: ${enn.coreDesire}`,
412	    moodLine,
413	    stressGrowth,
414	    agent.profile.secret ? `Secret: ${agent.profile.secret}` : '',
415	    agent.profile.innerConflict ? `Inner conflict: ${agent.profile.innerConflict}` : '',
416	  ].filter(Boolean).join('\n');
417	
418	  // ── Situation: nearby NPCs ──
419	  const nearbyNpcs: string[] = [];
420	  const neighborInfo: Map<string, string[]> = new Map();
421	
422	  for (const [otherId, other] of ctx.agents) {
423	    if (otherId === npcId || !other.state.alive) continue;
424	    if (isStatusAbsent(other.state.status)) continue;
425	    if (other.state.location === agent.state.location) {
426	      const statusTag = other.state.status ? ` [${other.state.status}]` : '';
427	      nearbyNpcs.push(`${other.profile.name} (${other.profile.role})${statusTag}`);
428	    }
429	  }
430	
431	  // Neighboring locations with who's there
432	  const currentLoc = ctx.locations.get(agent.state.location);
433	  if (currentLoc) {
434	    for (const connName of currentLoc.connections) {
435	      const npcsAt: string[] = [];
436	      for (const [otherId, other] of ctx.agents) {
437	        if (otherId === npcId || !other.state.alive) continue;
438	        if (isStatusAbsent(other.state.status)) continue;
439	        if (other.state.location === connName) {
440	          npcsAt.push(`${other.profile.name} (${other.profile.role})`);
441	        }
442	      }
443	      neighborInfo.set(connName, npcsAt);
444	    }
445	  }
446	
447	  // ── Instinct descriptions (procedural, personality-driven) ──
448	  const instincts: string[] = [];
449	  for (const sa of scored) {
450	    // Interpolate situational context from affordance instinctContext template + target.extra
451	    let context: string | undefined;
452	    if (sa.definition.instinctContext) {
453	      const vars = buildVarMap(sa.target);
454	      context = interpolate(sa.definition.instinctContext, vars);
455	    }
456	
457	    const desc = buildInstinctDescription(
458	      {
459	        id: sa.definition.id,
460	        score: sa.score,
461	        severity: sa.definition.severity ?? 5,
462	        label: sa.definition.label,
463	        targetName: sa.target.targetName,
464	        resistTraits: sa.definition.resistTraits,
465	        considerationCount: getConsiderationCount(npcId, sa.definition.id),
466	        context,
467	      },
468	      agent.profile,
469	      agent.state.mood,
470	    );
471	    instincts.push(`[${getTierName(sa.score)}] ${sa.definition.id}${sa.target.targetName ? ` → ${sa.target.targetName}` : ''}: ${desc}`);
472	    // Track consideration (NPC saw this option)
473	    trackConsideration(npcId, sa.definition.id);
474	  }
475	
476	  // ── Available actions (dynamic vocabulary) ──
477	  const locationNames = Array.from(ctx.locations.values()).map((l) => l.name);
478	  const aliveNpcNames = Array.from(ctx.agents.entries())
479	    .filter(([id, a]) => {
480	      if (id === npcId || !a.state.alive || a.profile.isPlayer) return false;
481	      return !isStatusAbsent(a.state.status);
482	    })
483	    .map(([, a]) => a.profile.name);
484	
485	  // ── Duty target collection (Tier 2: urge) ──
486	  // NPC names that are targets of duty affordances with score >= URGE_THRESHOLD
487	  // "talk" is blocked for these targets — duty action is the only way to interact
488	  const dutyTargetNames = new Set<string>();
489	  const dutyConstraintLines: string[] = [];
490	  for (const sa of scored) {
491	    if (sa.score >= URGE_THRESHOLD && sa.definition.isDuty) {
492	      dutyTargetNames.add(sa.target.targetName);
493	      dutyConstraintLines.push(
494	        `To interact with ${sa.target.targetName}, you must use '${sa.definition.id}' — your duty demands it.`,
495	      );
496	    }
497	  }
498	
499	  const actionLines: string[] = [
500	    'go — move to a location (set target to location name)',
501	  ];
502	  if (dutyTargetNames.size === 0) {
503	    actionLines.push('talk — talk to someone (set target to NPC name)');
504	  }
505	  actionLines.push('wait — stay and observe');
506	  actionLines.push('announce — say something to everyone here (set target to your words)');
507	
508	  // Add module-registered action verbs from scored affordances
509	  const addedVerbs = new Set<string>();
510	  for (const sa of scored) {
511	    const verb = sa.definition.actionVerb ?? sa.definition.id;
512	    const desc = sa.definition.actionDescription;
513	    if (desc && !addedVerbs.has(verb)) {
514	      actionLines.push(`${verb} — ${desc} (set target to NPC name)`);
515	      addedVerbs.add(verb);
516	    }
517	  }
518	
519	  // ── Build neighbor lines ──
520	  const neighborLines: string[] = [];
521	  for (const [locId, npcs] of neighborInfo) {
522	    const displayName = locationDisplayName(locId, ctx.locations);
523	    if (npcs.length > 0) {
524	      neighborLines.push(`  ${displayName}: ${npcs.join(', ')}`);
525	    } else {
526	      neighborLines.push(`  ${displayName}: empty`);
527	    }
528	  }
529	
530	  // ── User prompt (beliefs + relationships near instincts for attention) ──
531	  const userParts = [
532	    `SITUATION:`,
533	    `You are at ${locationDisplayName(agent.state.location, ctx.locations)}. Time: ${ctx.period}.`,
534	    nearbyNpcs.length > 0
535	      ? `Nearby: ${nearbyNpcs.join(', ')}.`
536	      : 'You are alone here.',
537	    neighborLines.length > 0 ? `Neighboring locations:\n${neighborLines.join('\n')}` : '',
538	    '',
539	    // Beliefs + relationships in user prompt (not system) — avoids "lost middle" problem
540	    ...(beliefSummary ? [`WHAT YOU KNOW:`, beliefSummary, ''] : []),
541	    ...(relSummary ? [`PEOPLE YOU KNOW:`, relSummary, ''] : []),
542	    'YOUR INSTINCTS (the stronger the urge, the harder it is to resist):',
543	    ...instincts,
544	    '',
545	    'AVAILABLE ACTIONS:',
546	    ...actionLines.map((l) => `  ${l}`),
547	    '',
548	    ...(dutyConstraintLines.length > 0 ? ['DUTY CONSTRAINTS:', ...dutyConstraintLines, ''] : []),
549	    `LOCATIONS: ${locationNames.join(', ')}`,
550	    `NPCs: ${aliveNpcNames.map(n => hasRecentTalk(npcId, n, ctx.gameMinute) ? `${n} (spoke recently — try someone else)` : n).join(', ')}`,
551	    '',
552	    'Choose ONE action. Use EXACTLY the action words listed above.',
553	    'Respond with: action (verb), target (NPC name or location), reason (one sentence in character).',
554	  ].filter((l) => l !== undefined).join('\n');
555	
556	  return { system: systemParts, user: userParts };
557	}
558	
559	// ─── Recent Talk Target Tracking (anti-repeat) ───
560	
561	const _recentTalkTargets = new Map<string, Map<string, number>>(); // npcId → targetName → lastGameMinute
562	
563	/** Check if NPC talked to this target recently (within 120 game minutes = 2h) */
564	function hasRecentTalk(npcId: string, targetName: string, gameMinute: number): boolean {
565	  const lastMinute = _recentTalkTargets.get(npcId)?.get(targetName) ?? -Infinity;
566	  return gameMinute - lastMinute < 120;
567	}
568	
569	/** Record that NPC talked to target */
570	export function recordTalkTarget(npcId: string, targetName: string, gameMinute: number): void {
571	  if (!_recentTalkTargets.has(npcId)) _recentTalkTargets.set(npcId, new Map());
572	  _recentTalkTargets.get(npcId)!.set(targetName, gameMinute);
573	}
574	
575	// ─── Consideration Tracking (escalation) ───
576	
577	const _considerations = new Map<string, Map<string, number>>();
578	
579	function getConsiderationCount(npcId: string, affId: string): number {
580	  return _considerations.get(npcId)?.get(affId) ?? 0;
581	}
582	
583	function trackConsideration(npcId: string, affId: string): void {
584	  if (!_considerations.has(npcId)) _considerations.set(npcId, new Map());
585	  const npcMap = _considerations.get(npcId)!;
586	  npcMap.set(affId, (npcMap.get(affId) ?? 0) + 1);
587	}
588	
589	/** Reset consideration count when NPC acts on an affordance (or mood recovers) */
590	export function resetConsideration(npcId: string, affId?: string): void {
591	  if (affId) {
592	    _considerations.get(npcId)?.delete(affId);
593	  } else {
594	    _considerations.delete(npcId);
595	  }
596	}
597	
598	// ─── LLM Call ───
599	
600	/** Build volition schema with dynamic action enum from registered verbs */
601	let _volitionSchema: import('./llm-client').LlmJsonSchema | null = null;
602	function getVolitionSchema(): import('./llm-client').LlmJsonSchema {
603	  if (!_volitionSchema) {
604	    const engineVerbs = Object.keys(ENGINE_ACTIONS); // go, talk, wait, announce
605	    const moduleVerbs = getAllRegisteredVerbs();       // steal, kill, attack, investigate, etc.
606	    const allVerbs = [...new Set([...engineVerbs, ...moduleVerbs])];
607	    _volitionSchema = {
608	      name: 'npc_decision',
609	      strict: true,
610	      schema: {
611	        type: 'object',
612	        properties: {
613	          action: { type: 'string', enum: allVerbs },
614	          target: { type: 'string', description: 'NPC name, location name, or empty string' },
615	          reason: { type: 'string', description: 'One sentence in character' },
616	        },
617	        required: ['action', 'target', 'reason'],
618	        additionalProperties: false,
619	      },
620	    };
621	  }
622	  return _volitionSchema;
623	}
624	
625	// ─── Decision Resolution ───
626	
627	/** Engine-level actions that don't go through ACTION_VERB_MAP */
628	const ENGINE_ACTIONS: Record<string, (npc: string | undefined, loc: string | undefined, raw: string, why: string) => ParsedIntention | null> = {
629	  go: (_npc, loc, _raw, why) => loc ? { action: 'go', target: loc, why } : null,
630	  talk: (npc, _loc, _raw, why) => npc ? { action: 'talk', target: npc, detail: why || 'catch up', why } : null,
631	  wait: (_npc, _loc, _raw, why) => ({ action: 'wait', why }),
632	  announce: (_npc, _loc, raw, why) => raw ? { action: 'announce', detail: raw, why } : null,
633	};
634	
635	function resolveDecision(
636	  action: string,
637	  resolvedNpc: string | undefined,
638	  resolvedLocation: string | undefined,
639	  rawTarget: string,
640	  reason: string,
641	): ParsedIntention | null {
642	  // Check engine-level actions first
643	  const engineHandler = ENGINE_ACTIONS[action];
644	  if (engineHandler) return engineHandler(resolvedNpc, resolvedLocation, rawTarget, reason);
645	
646	  // Check module-registered verbs (steal, kill, investigate, arrest, etc.)
647	  const verbIds = getAffordanceIdsForVerb(action);
648	  if (verbIds.length > 0) {
649	    return { action, target: resolvedNpc || undefined, why: reason };
650	  }
651	
652	  return null;
653	}
654	
655	// ─── LLM Call ───
656	
657	async function callLlm(agent: Agent, system: string, user: string, volitionTemp?: number): Promise<string | null> {
658	  const temperature = volitionTemp ?? 0.35;
659	  // classify внутри façade: семафор/retry/null-on-error
660	  const result = await classify<unknown>('volition', {
661	    system,
662	    user,
663	    schema: getVolitionSchema(),
664	    agentContext: { id: agent.profile.id },
665	    samplingOverride: { temperature },
666	    maxTokensOverride: 100,
667	  });
668	  // Caller'ы ждут строку — возвращаем JSON.stringify (façade уже распарсил, нам надо вернуть как строку)
669	  return result === null ? null : JSON.stringify(result);
670	}
671	
672	/** Exact case-insensitive match against a list of valid names */
673	function matchName(input: string, validNames: string[]): string | null {
674	  if (!input) return null;
675	  const lower = input.toLowerCase();
676	  // Exact match
677	  const exact = validNames.find((n) => n.toLowerCase() === lower);
678	  if (exact) return exact;
679	  // Fuzzy: input contains a valid name (e.g. "Garrett and Traveler" → "Garrett")
680	  const sorted = [...validNames].sort((a, b) => b.length - a.length);
681	  for (const name of sorted) {
682	    if (lower.includes(name.toLowerCase())) return name;
683	  }
684	  return null;
685	}
686	
687	/** Match NPC name at the start of input, return matched name and remaining text */
688	// ─── Intention → Goal Mapping ───
689	
690	function intentionToGoal(
691	  parsed: ParsedIntention,
692	  npcId: string,
693	  agent: Agent,
694	  scored: ScoredAffordance[],
695	  ctx: AffordanceContext,
696	): NpcGoal | null {
697	  const home = ctx.npcHomes.get(npcId) ?? agent.state.location;
698	
699	  switch (parsed.action) {
700	    case 'wait':
701	      return null;
702	
703	    case 'go': {
704	      if (!parsed.target) return null;
705	      const targetLocId = resolveLocationId(parsed.target, ctx.locations);
706	      if (targetLocId === agent.state.location) return null; // already there
707	      return {
708	        id: crypto.randomUUID(),
709	        type: 'wander',
710	        ownerId: npcId,
711	        priority: 2,
712	        state: 'pending',
713	        steps: [{ action: 'move_to', location: targetLocId }],
714	        currentStep: 0,
715	        data: { reason: parsed.why },
716	        createdAtMinute: 0,
717	        homeLocation: home,
718	      };
719	    }
720	
721	    case 'talk': {
722	      if (!parsed.target) return null;
723	      // Find NPC by name
724	      const targetEntry = findNpcByName(parsed.target, npcId, ctx);
725	      if (!targetEntry) return null;
726	      const [targetId, targetAgent] = targetEntry;
727	
728	      // Social-only context (only socialize affordance scored): move to target, let TopicEngine handle conversation
729	      // Purposeful context (crime/duty affordances scored): move + interact with specific purpose
730	      const socialOnly = scored.every(s => s.definition.socialOnly === true);
731	
732	      // Social visit: skip if pair is on conversation cooldown (avoids repetitive targeting)
733	      if (socialOnly && ctx.isPairOnCooldown?.(npcId, targetId)) {
734	        console.log(`  [AL:retry] ${agent.profile.name}: visit ${targetAgent.profile.name} rejected (pair cooldown) — 15min cooldown`);
735	        // Minimal cooldown (15 min) instead of extended (180 min) — system rejected, not NPC's choice
736	        if (ctx.decisionCooldowns) {
737	          ctx.decisionCooldowns.set(npcId, ctx.gameMinute + 15);
738	        }
739	        return null;
740	      }
741	
742	      const steps: GoalStep[] = [];
743	      const targetInTransit = targetAgent.state.inTransit;
744	      if (agent.state.location !== targetAgent.state.location || targetInTransit) {
745	        // If target is in transit, move to their destination (they'll arrive there)
746	        const targetLoc = targetInTransit && targetAgent.state.transitTo
747	          ? targetAgent.state.transitTo
748	          : targetAgent.state.location;
749	        steps.push({ action: 'move_to', location: targetLoc });
750	      }
751	      if (!socialOnly) {
752	        // Purposeful talk — directed interaction with specific topic
753	        steps.push({
754	          action: 'interact',
755	          targetId,
756	          purpose: parsed.detail ?? 'general conversation',
757	          importance: 4,
758	        });
759	      }
760	      // Social-only + co-located: linger briefly so scheduler can pair them for conversation.
761	      // Without this, schedule check immediately creates a move goal and the NPC leaves.
762	      if (steps.length === 0) {
763	        console.log(`  [AL:debug] ${agent.profile.name}: co-located with ${targetAgent.profile.name}, lingering for conversation`);
764	        steps.push({ action: 'wait', ticks: 2 });
765	      }
766	      return {
767	        id: crypto.randomUUID(),
768	        type: socialOnly ? 'visit' : 'social',
769	        ownerId: npcId,
770	        priority: socialOnly ? 2 : 3,
771	        state: 'pending',
772	        steps,
773	        currentStep: 0,
774	        data: { targetName: parsed.target, topic: parsed.detail, reason: parsed.why },
775	        createdAtMinute: 0,
776	        homeLocation: home,
777	      };
778	    }
779	
780	    case 'announce': {
781	      if (!parsed.detail) return null;
782	      return {
783	        id: crypto.randomUUID(),
784	        type: 'announce',
785	        ownerId: npcId,
786	        priority: 2,
787	        state: 'pending',
788	        steps: [{ action: 'announce', message: parsed.detail, importance: 3 }],
789	        currentStep: 0,
790	        data: { reason: parsed.why },
791	        createdAtMinute: 0,
792	        homeLocation: home,
793	      };
794	    }
795	
796	    default: {
797	      // Module-registered action verbs → affordance IDs lookup
798	      const affordanceIds = getAffordanceIdsForVerb(parsed.action);
799	      if (affordanceIds.length > 0) {
800	        const aff = affordanceIds.reduce<ScoredAffordance | null>(
801	          (found, id) => found ?? scored.find((s) => s.definition.id === id) ?? null,
802	          null,
803	        );
804	        if (aff) {
805	          const goal = buildGoalFromAffordance(aff, npcId, agent, ctx);
806	          goal.data.reason = parsed.why;
807	          return goal;
808	        }
809	      }
810	      return null;
811	    }
812	  }
813	}
