815	/** Find NPC entry by display name */
816	function findNpcByName(name: string, excludeId: string, ctx: AffordanceContext): [string, Agent] | null {
817	  const lower = name.toLowerCase();
818	  for (const [id, agent] of ctx.agents) {
819	    if (id === excludeId || !agent.state.alive || agent.profile.isPlayer) continue;
820	    if (agent.profile.name.toLowerCase() === lower) return [id, agent];
821	  }
822	  return null;
823	}
