890	// ─── Declarative Step Template Resolver ───
891	
892	function buildSteps(
893	  aff: AffordanceDefinition,
894	  npcId: string,
895	  agent: Agent,
896	  target: AffordanceTarget,
897	  ctx: AffordanceContext,
898	): GoalStep[] {
899	  // Use declarative templates if defined
900	  if (aff.stepTemplates) {
901	    return resolveTemplates(aff.stepTemplates, npcId, agent, target, ctx);
902	  }
903	
904	  // Fallback for affordances without templates
905	  const steps: GoalStep[] = [];
906	  if (agent.state.location !== target.targetLocation) {
907	    steps.push({ action: 'move_to', location: target.targetLocation });
908	  }
909	  steps.push({ action: 'interact', targetId: target.targetId, purpose: aff.label, importance: 5 });
910	  return steps;
911	}
