913	/**
914	 * Resolve step templates into concrete GoalSteps.
915	 * Handles location references ($target, $home, $extra.KEY),
916	 * target ID references ($target), and string interpolation ({var:fallback}).
917	 */
918	function resolveTemplates(
919	  templates: StepTemplate[],
920	  npcId: string,
921	  agent: Agent,
922	  target: AffordanceTarget,
923	  ctx: AffordanceContext,
924	): GoalStep[] {
925	  const home = ctx.npcHomes.get(npcId) ?? agent.state.location;
926	  const vars = buildVarMap(target);
927	  const steps: GoalStep[] = [];
928	
929	  for (const tmpl of templates) {
930	    switch (tmpl.action) {
931	      case 'move_to': {
932	        const location = resolveLocation(tmpl.location ?? '$target', target, home);
933	        if (tmpl.skipIfAt && agent.state.location === location) continue;
934	        steps.push({ action: 'move_to', location });
935	        break;
936	      }
937	      case 'interact': {
938	        const targetId = resolveTargetId(tmpl.targetId ?? '$target', target);
939	        steps.push({
940	          action: 'interact',
941	          targetId,
942	          purpose: interpolate(tmpl.purpose ?? '', vars),
943	          importance: tmpl.importance ?? 5,
944	          beliefTransfer: tmpl.beliefTransfer,
945	          beliefTransferDirection: tmpl.beliefTransferDirection,
946	          evaluateSuspect: tmpl.evaluateSuspect,
947	        });
948	        break;
949	      }
950	      case 'interact_present': {
951	        steps.push({
952	          action: 'interact_present',
953	          purpose: interpolate(tmpl.purpose ?? '', vars),
954	          importance: tmpl.importance ?? 5,
955	          filter: tmpl.filter,
956	          beliefTransfer: tmpl.beliefTransfer,
957	        });
958	        break;
959	      }
960	      case 'announce': {
961	        steps.push({
962	          action: 'announce',
963	          message: interpolate(tmpl.message ?? '', vars),
964	          importance: tmpl.importance ?? 3,
965	        });
966	        break;
967	      }
968	      case 'wait': {
969	        steps.push({ action: 'wait', ticks: tmpl.ticks ?? 1 });
970	        break;
971	      }
972	      // Generic handler for all module-registered step types (steal, arrest, trade, etc.)
973	      // Resolves $target references and interpolates string fields automatically.
974	      default: {
975	        const step: Record<string, unknown> = { action: tmpl.action };
976	        if (tmpl.targetId) step.targetId = resolveTargetId(tmpl.targetId, target);
977	        if (tmpl.importance !== undefined) step.importance = tmpl.importance;
978	        // Resolve remaining template fields (interpolate strings, copy rest)
979	        const handled = new Set(['action', 'targetId', 'importance', 'location', 'skipIfAt']);
980	        for (const [key, value] of Object.entries(tmpl)) {
981	          if (handled.has(key) || step[key] !== undefined) continue;
982	          step[key] = typeof value === 'string' ? interpolate(value, vars) : value;
983	        }
984	        steps.push(step as GoalStep);
985	        break;
986	      }
987	    }
988	  }
989	
990	  return steps;
991	}
992	
993	/** Build variable map for string interpolation */
994	function buildVarMap(target: AffordanceTarget): Record<string, string> {
995	  const vars: Record<string, string> = {
996	    targetName: target.targetName,
997	    targetId: target.targetId,
998	    targetLocation: target.targetLocation,
999	  };
1000	  // Add all extra fields as string vars
1001	  if (target.extra) {
1002	    for (const [key, value] of Object.entries(target.extra)) {
1003	      if (typeof value === 'string') vars[key] = value;
1004	    }
1005	  }
1006	  // Computed: relationshipDesc from relationship
1007	  const rel = vars.relationship;
1008	  if (rel) {
1009	    vars.relationshipDesc = getRelationshipLabel(rel);
1010	  }
1011	  return vars;
1012	}
1013	
1014	/** Resolve location reference: $target, $home, $extra.KEY, or literal */
1015	function resolveLocation(ref: string, target: AffordanceTarget, home: string): string {
1016	  if (ref === '$target') return target.targetLocation;
1017	  if (ref === '$home') return home;
1018	  if (ref.startsWith('$extra.')) {
1019	    const key = ref.slice(7);
1020	    return (target.extra?.[key] as string) ?? target.targetLocation;
1021	  }
1022	  return ref; // literal location name
1023	}
1024	
1025	/** Resolve target ID reference: $target or literal */
1026	function resolveTargetId(ref: string, target: AffordanceTarget): string {
1027	  return ref === '$target' ? target.targetId : ref;
1028	}
1029	
1030	/** Interpolate {var:fallback} patterns in a template string */
1031	function interpolate(template: string, vars: Record<string, string>): string {
1032	  return template.replace(/\{(\w+)(?::([^}]*))?\}/g, (_, key, fallback) => {
1033	    return vars[key] ?? fallback ?? key;
1034	  });
1035	}
