1037	// ─── Cooldown Helpers ───
1038	
1039	function setAffordanceCooldown(ctx: AffordanceContext, npcId: string, affordanceId: string, gameMinute: number, aff?: AffordanceDefinition): void {
1040	  if (!ctx.cooldowns || !affordanceId) return;
1041	  let npcMap = ctx.cooldowns.get(npcId);
1042	  if (!npcMap) {
1043	    npcMap = new Map();
1044	    ctx.cooldowns.set(npcId, npcMap);
1045	  }
1046	  const cooldown = aff?.cooldownOverride ?? ctx.affordanceCooldownMinutes ?? DEFAULT_AFFORDANCE_COOLDOWN;
1047	  npcMap.set(affordanceId, gameMinute + cooldown);
1048	}
1049	
1050	function setDecisionCooldown(ctx: AffordanceContext, npcId: string, gameMinute: number): void {
1051	  if (!ctx.decisionCooldowns) return;
1052	  ctx.decisionCooldowns.set(npcId, gameMinute + (ctx.decisionCooldownMinutes ?? DEFAULT_DECISION_COOLDOWN));
1053	}
1054	
1055	function setDecisionCooldownExtended(ctx: AffordanceContext, npcId: string, gameMinute: number): void {
1056	  if (!ctx.decisionCooldowns) return;
1057	  const base = ctx.decisionCooldownMinutes ?? DEFAULT_DECISION_COOLDOWN;
1058	  ctx.decisionCooldowns.set(npcId, gameMinute + base * 3);
1059	}
