400	
401	function findReactiveTarget(
402	  aff: AffordanceDefinition,
403	  npcId: string,
404	  agent: Agent,
405	  ctx: AffordanceContext,
406	  event: WorldEvent,
407	): AffordanceTarget | null {
408	  // Check reactive registry first (registered by affordance id, not targetFinder)
409	  const finder = REACTIVE_TARGET_FINDERS.get(aff.id);
410	  if (finder) return finder(npcId, agent, ctx, event, aff);
411	  // Fallback to generic role-based finder
412	  if (aff.targetRole) return findByRole(aff.targetRole, npcId, agent, ctx);
413	  return null;
