92	  isRoutine?: boolean;     // true for schedule/routine goals — no mood boost on completion
93	  // Goal watchdog bookkeeping (sweepStuckGoals): last observed step + game-minute it last advanced.
94	  // Lazily initialized; used to detect a goal making no step progress for too long.
95	  lastProgressStep?: number;
96	  lastProgressMinute?: number;
97	}
