51	/** Gather evidence grouped by quality tier */
52	function gatherEvidenceGrouped(suspect: Agent, agents: Map<string, Agent>): { strong: string[]; moderate: string[]; weak: string[]; crimeTypes: Set<string> } {
53	  const strong: string[] = [];
54	  const moderate: string[] = [];
55	  const weak: string[] = [];
56	  const crimeTypes = new Set<string>();
57	  const perpetratorName = suspect.profile.name;
58	  const suspectId = suspect.profile.id;
59	  const matchesSuspect = (field: string | null | undefined): boolean =>
60	    !!field && (field === perpetratorName || field === suspectId);
61	
62	  for (const [, agent] of agents) {
63	    if (!agent.state.alive || agent.profile.id === suspectId) continue;
64	    const beliefs = agent.state.beliefs?.getAllBeliefs() ?? [];
65	    for (const b of beliefs) {
66	      if (b.confidence < 0.3 || (!matchesSuspect(b.subject) && !matchesSuspect(b.object))) continue;
67	      const sourceLabel = getBeliefSourceLabel(b.source);
68	      const eventLabel = getEventLabel(b.eventType);
69	      if (!eventLabel) continue;
70	      const subjectDisplay = b.subject ? (agents.get(b.subject)?.profile.name ?? b.subject) : 'unknown';
71	      const objectDisplay = b.object ? (agents.get(b.object)?.profile.name ?? b.object) : 'unknown';
72	      const line = `${agent.profile.name} (${sourceLabel}, ${Math.round(b.confidence * 100)}%): ${subjectDisplay} committed ${eventLabel} against ${objectDisplay}`;
73	
74	      if (b.eventType) crimeTypes.add(b.eventType);
75	
76	      if (isFirsthand(b.source) || b.source === 'evidence') {
77	        strong.push(line);
78	      } else if (b.source === 'deduction' || b.source === 'interrogation' || b.confidence >= 0.6) {
79	        moderate.push(line);
80	      } else {
81	        weak.push(line);
82	      }
83	    }
84	  }
85	
86	  return { strong, moderate, weak, crimeTypes };
87	}
