89	/** Build suspect defense text from H trait + own beliefs */
90	function buildSuspectDefense(suspect: Agent): string {
91	  const h = suspect.profile.bigFive?.honesty ?? 0.5;
92	  const name = suspect.profile.name;
93	
94	  // Check if suspect actually has perpetrator belief (they KNOW they did it)
95	  const hasPerpBelief = suspect.state.beliefs?.getAllBeliefs().some(
96	    (b: Belief) => b.source === 'perpetrator' && b.subject === suspect.profile.id,
97	  ) ?? false;
98	
99	  if (!hasPerpBelief) {
100	    // Genuinely innocent (or doesn't remember) — defense is more convincing
101	    return `${name} maintains their innocence with steady conviction. They provide clear answers and seem genuinely confused by the accusations. ${h >= 0.6 ? 'Their sincerity is apparent.' : 'Though their manner is rough, nothing suggests deception.'}`;
102	  }
103	
104	  // Guilty — H trait determines how well they lie
105	  if (h >= 0.7) return `${name} appears genuinely remorseful. They lower their eyes and do not deny the accusations directly. Their voice cracks with guilt.`;
106	  if (h >= 0.4) return `${name} is evasive and uncomfortable. They offer no clear defense but do not confess either. Their answers are vague and contradictory.`;
107	  return `${name} vehemently denies all charges. They claim innocence with aggressive confidence, dismissing every piece of evidence and blaming others.`;
108	}
109	
110	/** Build judge personality context from PM */
111	function buildJudgeContext(judge: Agent): string {
112	  const pm = judge.profile.bigFive;
113	  if (!pm) return '';
114	  const lines: string[] = [];
115	  if (pm.conscientiousness >= 0.7) lines.push('Your sense of duty demands order and precedent. The law must be applied consistently.');
116	  if (pm.agreeableness >= 0.7) lines.push('You see a person before you, not just a criminal. Rehabilitation matters.');
117	  else if (pm.agreeableness <= 0.3) lines.push('The village needs to see consequences. Leniency invites more crime.');
118	  if (pm.honesty >= 0.8) lines.push('Truth and fairness are sacred. Punish honestly — neither too much nor too little.');
119	  if (pm.neuroticism >= 0.6) lines.push('The weight of judgment burdens you. What if you are wrong?');
120	  return lines.join(' ');
121	}
