123	/** Build community pressure summary — relationships to suspect AND victim, completed goals */
124	function buildCommunityPressure(suspect: Agent, victimId: string | null, agents: Map<string, Agent>, goalManager: GoalManager): string {
125	  const lines: string[] = [];
126	  const suspectId = suspect.profile.id;
127	
128	  for (const [id, agent] of agents) {
129	    if (!agent.state.alive || id === suspectId || agent.profile.isPlayer) continue;
130	
131	    // Check completed goals related to this case
132	    const goals = goalManager?.getGoals(id) ?? [];
133	    const demandedJustice = goals.some((g: NpcGoal) => g.type === 'demand_justice' && g.state === 'completed');
134	    const testified = goals.some((g: NpcGoal) => g.type === 'testify' && g.state === 'completed');
135	
136	    // Relationship to victim (friend of victim → wants punishment)
137	    const relToVictim = victimId ? agent.state.relationships?.getRelationship(victimId) : null;
138	    const closenessToVictim = relToVictim?.sentiment ?? 0;
139	
140	    // Relationship to suspect
141	    const relToSuspect = agent.state.relationships?.getRelationship(suspectId);
142	    const sentimentToSuspect = relToSuspect?.sentiment ?? 0;
143	
144	    if (demandedJustice) {
145	      lines.push(`${agent.profile.name} publicly demanded justice — wants harsh punishment`);
146	    } else if (testified) {
147	      lines.push(`${agent.profile.name} testified against the suspect`);
148	    } else if (closenessToVictim > 0.3) {
149	      lines.push(`${agent.profile.name} (close to the victim): likely wants punishment`);
150	    } else if (sentimentToSuspect >= 0.3) {
151	      lines.push(`${agent.profile.name} (sympathetic to suspect): urges leniency`);
152	    }
153	  }
154	
155	  return lines.length > 0 ? lines.join('\n') : 'No notable community pressure.';
156	}
