158	/** Check if suspect is guilty (perpetrator of an active crime scene) */
159	function checkGuilt(suspectId: string, crimeScenes?: Map<string, CrimeScene[]>): boolean {
160	  if (!crimeScenes) return false;
161	  for (const scenes of crimeScenes.values()) {
162	    for (const scene of scenes) {
163	      if (scene.active && scene.perpetratorId === suspectId) return true;
164	    }
165	  }
166	  return false;
167	}
168	
169	/** Evaluate interrogation outcome based on guilt + honesty trait */
170	function evaluateInterrogationOutcome(owner: Agent, target: Agent, currentDay: number, crimeScenes: Map<string, CrimeScene[]>): void {
171	  if (!owner.state.beliefs) return;
172	  const deductionBelief = owner.state.beliefs.getAllBeliefs().find(
173	    (b: Belief) => b.source === 'deduction' && b.subject === target.profile.id,
174	  );
175	  if (!deductionBelief) return;
176	
177	  const isGuilty = checkGuilt(target.profile.id, crimeScenes);
178	  const honesty = target.profile.bigFive.honesty;
179	  const HONESTY_THRESHOLD = 0.6;
180	  const CONFESSION_CONFIDENCE = 0.85;
181	  const NERVOUS_BOOST = 0.15;
182	  const ALIBI_DROP = 0.2;
183	
184	  if (isGuilty) {
185	    if (honesty >= HONESTY_THRESHOLD) {
186	      deductionBelief.confidence = Math.min(1, CONFESSION_CONFIDENCE);
187	      deductionBelief.lastUpdated = currentDay;
188	    } else {
189	      deductionBelief.confidence = Math.min(1, deductionBelief.confidence + NERVOUS_BOOST);
190	      deductionBelief.lastUpdated = currentDay;
191	    }
192	  } else {
193	    deductionBelief.confidence = Math.max(0.1, deductionBelief.confidence - ALIBI_DROP);
194	    deductionBelief.lastUpdated = currentDay;
195	  }
196	}
