330	      ctx.evidenceLayer?.discover(e.id, goal.ownerId);
331	      if (!e.subjectName || !owner.state.beliefs) continue;
332	      // addBelief now deduplicates by (eventType, object, source).
333	      // evidence beliefs coexist with observation/testimony beliefs as separate proof.
334	      // Multiple evidence pieces about same suspect merge (cumulative physical proof).
335	      owner.state.beliefs.addBelief({
336	        id: crypto.randomUUID(),
337	        eventType: e.eventType,
338	        subject: e.subjectId ?? e.subjectName,
339	        object: e.objectId ?? e.objectName ?? '',
340	        location: owner.state.location,
341	        confidence: e.weight,
342	        source: 'evidence',
343	        sourceNpcId: null,
344	        gameDay: currentDay,
345	        lastUpdated: currentDay,
346	      });
347	      suspectCount++;
348	    }
349	    const scenes = ctx.crimeScenes?.get(owner.state.location) ?? [];
350	    const activeScene = scenes.find((s: CrimeScene) => s.active);
351	    const affectedName = activeScene?.victimId ? agents.get(activeScene.victimId)?.profile.name ?? 'unknown' : 'unknown';
352	    const crimeLabel = activeScene?.crimeType ? (getEventLabel(activeScene.eventType ?? activeScene.crimeType) ?? 'crime') : 'crime';
353	    await owner.observe(`I examined the crime scene. ${suspectCount > 0 ? `Found ${suspectCount} suspect(s) in the ${crimeLabel} of ${affectedName}.` : `Reinforced suspicions about ${affectedName}.`}`, step.importance);
354	    goal.currentStep++;
355	    return { ...baseResult, action: 'examine_scene', description: `${owner.profile.name} examined evidence: ${undiscovered.length} clue(s), ${suspectCount} suspect(s)` };
356	  });
