358	  registerStepHandler('sentence_npc', async (ctx: StepExecutionContext): Promise<GoalActionResult | null> => {
359	    const { goal, owner, agents } = ctx;
360	    const step = ctx.step as SentenceNpcStep;
361	    const baseResult = { goalId: goal.id, goalType: goal.type, ownerId: goal.ownerId, ownerName: owner.profile.name };
362	    const target = agents.get(step.targetId as string);
363	    if (!target || target.state.status !== 'detained') { goal.currentStep++; return { ...baseResult, action: 'sentence_npc', description: `${owner.profile.name}: no detained suspect` }; }
364	
365	    // 1. Determine crime severity from crime scenes, fallback to beliefs
366	    let crimeSeverity = 3; // conservative fallback
367	    let affectedName: string | null = null;
368	    let victimId: string | null = null;
369	    let crimeEventType: string | null = null;
370	    if (ctx.crimeScenes) {
371	      for (const scenes of ctx.crimeScenes.values()) {
372	        for (const scene of scenes) {
373	          if (scene.perpetratorId === step.targetId && scene.active !== false) {
374	            crimeEventType = scene.eventType ?? scene.crimeType ?? null;
375	            if (crimeEventType && CRIME_SEVERITY[crimeEventType]) {
376	              crimeSeverity = CRIME_SEVERITY[crimeEventType];
377	            }
378	            victimId = scene.victimId ?? null;
379	            if (victimId) {
380	              affectedName = agents.get(victimId)?.profile.name ?? null;
381	            }
382	            break;
383	          }
384	        }
385	        if (crimeEventType) break;
386	      }
387	    }
388	    // Fallback: if no crime scene found, infer severity from evidence beliefs
389	    if (!crimeEventType) {
390	      const evidence = gatherEvidenceGrouped(target, agents);
391	      for (const et of evidence.crimeTypes) {
392	        if (CRIME_SEVERITY[et] && CRIME_SEVERITY[et] > crimeSeverity) {
393	          crimeSeverity = CRIME_SEVERITY[et];
394	          crimeEventType = et;
395	        }
396	      }
397	    }
398	
399	    // 2. Get available verdicts for this crime severity
400	    const available = getAvailableVerdicts(crimeSeverity);
401	    const verdictIds = available.map(v => v.id);
402	    const verdictDescriptions = available.map(v => `${v.id}: ${v.label}`).join('\n');
403	
404	    // 3. Gather evidence grouped by quality
405	    const evidence = gatherEvidenceGrouped(target, agents);
406	    const evidenceLines: string[] = [];
407	    if (evidence.strong.length > 0) evidenceLines.push(`STRONG EVIDENCE (direct witness, physical proof):\n${evidence.strong.map(l => `  • ${l}`).join('\n')}`);
408	    if (evidence.moderate.length > 0) evidenceLines.push(`MODERATE EVIDENCE (deduction, interrogation):\n${evidence.moderate.map(l => `  • ${l}`).join('\n')}`);
409	    if (evidence.weak.length > 0) evidenceLines.push(`WEAK EVIDENCE (rumors, hearsay):\n${evidence.weak.map(l => `  • ${l}`).join('\n')}`);
410	    const evidenceSummary = evidenceLines.length > 0 ? evidenceLines.join('\n\n') : 'No evidence gathered against this suspect.';
411	    const totalEvidence = evidence.strong.length + evidence.moderate.length + evidence.weak.length;
412	
413	    // 4. Suspect defense (H trait)
414	    const suspectDefense = buildSuspectDefense(target);
415	
416	    // 5. Community pressure (relationships to victim + completed goals)
417	    const communityPressure = buildCommunityPressure(target, victimId, agents, ctx.goalManager);
418	
419	    // 6. Judge personality context
420	    const judgeContext = buildJudgeContext(owner);
421	
422	    // 7. Build prompt + structured output
423	    const crimeLabel = crimeEventType ? (getEventLabel(crimeEventType) ?? 'crime') : 'crime';
424	    const system = `You are ${owner.profile.name}, the town magistrate. You must deliver a just verdict.\n${judgeContext}`;
425	    const user = [
426	      `${target.profile.name} the ${target.profile.role} stands accused of ${crimeLabel}${affectedName ? ` against ${affectedName}` : ''}.`,
427	      `Crime severity: ${crimeSeverity}/10.`,
428	      ``,
429	      evidenceSummary,
430	      ``,
431	      `SUSPECT'S DEFENSE:`,
432	      suspectDefense,
433	      ``,
434	      `COMMUNITY:`,
435	      communityPressure,
436	      ``,
437	      `AVAILABLE VERDICTS (choose one appropriate to evidence strength and crime severity):`,
438	      verdictDescriptions,
439	      ``,
440	      `Consider: strong evidence + severe crime → harsher verdict. Weak evidence → acquittal. Moderate crime → proportionate response.`,
441	    ].join('\n');
442	
443	    const verdictSchema: LlmJsonSchema = {
444	      name: 'verdict_decision',
445	      strict: true,
446	      schema: {
447	        type: 'object',
448	        properties: {
449	          verdict: { type: 'string', enum: verdictIds },
450	          reasoning: { type: 'string' },
451	        },
452	        required: ['verdict', 'reasoning'],
453	        additionalProperties: false,
454	      },
455	    };
456	
457	    // 8. LLM call via façade. classify ловит exceptions → null, façade оборачивает acquire/release.
458	    let chosenVerdict = 'release';
459	    let reasoning = '';
460	    const result = await classify<{ verdict: string; reasoning: string }>('verdict', {
461	      system,
462	      user,
463	      schema: verdictSchema,
464	      agentContext: { id: owner.profile.id }, // magistrate's per-NPC folder (for ClaudeCodeProvider)
465	      maxTokensOverride: 300,
466	      samplingOverride: { temperature: 0.4 },
467	    });
468	    if (result && verdictIds.includes(result.verdict)) {
469	      chosenVerdict = result.verdict;
470	      reasoning = result.reasoning ?? '';
471	    } else {
472	      const reason = result === null ? 'classify returned null' : `invalid verdict '${result.verdict}'`;
473	      console.warn(`[Verdict:ERROR] ${reason} for ${target.profile.name}, fallback=release`);
474	    }
475	
476	    // 9. Apply verdict effects
477	    const verdictDef = available.find(v => v.id === chosenVerdict) ?? available[0];
478	    const verdictLabel = verdictDef.label;
479	    console.log(`  [Verdict] ${owner.profile.name} → ${target.profile.name}: ${chosenVerdict} (severity ${crimeSeverity}, evidence ${totalEvidence}). ${reasoning}`);
480	
481	    if (chosenVerdict === 'exile') {
482	      target.state.status = 'exiled';
483	      ctx.goalManager.clearGoals(step.targetId as string);
484	      await owner.observe(`I sentenced ${target.profile.name} to permanent exile. ${reasoning}`, step.importance as number);
485	      await target.observe(`Magistrate ${owner.profile.name} banished me from the village forever. ${reasoning}`, step.importance as number);
486	      ctx.addMoodModifier(step.targetId as string, { source: 'sentence_exile', category: 'event', magnitude: -2.0, remaining: 1440, duration: 1440, decay: 'exponential' });
487	    } else if (chosenVerdict === 'imprisonment') {
488	      target.state.status = 'imprisoned';
489	      const durationDays = verdictDef.effects.durationDays ?? 2;
490	      const sentenceDay = owner.state.currentDay;
491	      const releaseDay = sentenceDay + durationDays;
492	      imprisonmentTimers.set(target.profile.id, releaseDay);
493	      await owner.observe(`I sentenced ${target.profile.name} to ${durationDays} days of imprisonment. ${reasoning}`, step.importance as number);
494	      await target.observe(`Magistrate ${owner.profile.name} sentenced me to ${durationDays} days of imprisonment. I must serve my time.`, step.importance as number);
495	      ctx.addMoodModifier(step.targetId as string, { source: 'sentence_imprisonment', category: 'event', magnitude: verdictDef.effects.moodShift, remaining: 720, duration: 720, decay: 'exponential' });
496	    } else if (chosenVerdict === 'release') {
497	      target.state.status = undefined as unknown as string;
498	      await owner.observe(`I released ${target.profile.name}. ${reasoning}`, step.importance as number);
499	      await target.observe(`Magistrate ${owner.profile.name} released me. I am free.`, step.importance as number);
500	      ctx.addMoodModifier(step.targetId as string, { source: 'sentence_release', category: 'event', magnitude: 0.3, remaining: 720, duration: 720, decay: 'exponential' });
501	    } else {
502	      // warning, fine — NPC is freed but punished. Social stigma remains.
503	      target.state.status = undefined as unknown as string;
504	      await owner.observe(`I gave ${target.profile.name} a ${verdictLabel.toLowerCase()}. ${reasoning}`, step.importance as number);
505	      await target.observe(`Magistrate ${owner.profile.name} sentenced me: ${verdictLabel.toLowerCase()}. The shame is public. ${reasoning}`, step.importance as number);
506	      ctx.addMoodModifier(step.targetId as string, { source: 'sentence_reaction', category: 'event', magnitude: verdictDef.effects.moodShift, remaining: 720, duration: 720, decay: 'exponential' });
507	      // Victim reaction: mild punishments may frustrate the victim
508	      if (victimId) {
509	        const victim = agents.get(victimId);
510	        if (victim?.state.alive) {
511	          victim.state.relationships?.adjustSentiment(step.targetId as string, -0.1);
512	          if (chosenVerdict === 'warning') {
513	            ctx.addMoodModifier(victimId as string, { source: 'verdict_frustration', category: 'pressure', magnitude: -0.1, remaining: 240, duration: 240, decay: 'linear' });
514	          }
515	        }
516	      }
517	    }
518	
519	    if (ctx.onCrimeEvent) {
520	      await ctx.onCrimeEvent({
521	        type: 'NPC_SENTENCED', subject: goal.ownerId, object: step.targetId as string,
522	        location: owner.state.location, importance: step.importance as number,
523	        payload: {
524	          judgeName: owner.profile.name, perpetratorName: target.profile.name,
525	          affectedName, verdict: chosenVerdict, verdictLabel, reasoning,
526	          crimeSeverity, evidenceCount: totalEvidence,
527	          releaseDay: chosenVerdict === 'imprisonment' ? imprisonmentTimers.get(target.profile.id) : undefined,
528	          affectedTargets: Array.from(agents.keys()),
529	        },
530	      });
531	    }
532	    goal.currentStep++;
533	    return { ...baseResult, action: 'sentence_npc', description: `${owner.profile.name} sentenced ${target.profile.name}: ${verdictLabel}` };
534	  });
