4	// ─── Mood Modifiers (SPEC-mood-modifiers) ───
5	
6	export interface MoodModifier {
7	  id: string;
8	  source: string;           // human-readable: 'argument_with_bess', 'social_stress'
9	  category: string;         // stacking group: 'social_stress', 'conversation', 'event', 'pressure', 'routine'
10	  magnitude: number;        // -0.35 to +0.35
11	  remaining: number;        // game minutes left (0 = permanent until removed)
12	  duration: number;         // original duration (for decay calc; 0 = permanent)
13	  decay: 'exponential' | 'linear' | 'none';
14	}
15	
16	/** Compute decayed effective magnitude of a modifier */
17	export function modifierEffective(m: MoodModifier): number {
18	  if (m.decay === 'none' || m.duration === 0) return m.magnitude;
19	  const ratio = m.remaining / m.duration;
20	  if (m.decay === 'exponential') return m.magnitude * ratio * ratio;
21	  return m.magnitude * ratio; // linear
22	}
